import{_ as a,o as e,c as n,a6 as t}from"./chunks/framework.BrkgobfX.js";const h=JSON.parse('{"title":"个性化与缓存 · 每人不同的页面怎么缓存","description":"「你好，张三」这种每人不同的页面，天生和共享缓存(CDN)水火不容——缓存了发给别人就是灾难。可我们又想要 CDN 的速度。这一章给出破局的整套工具：拆分静态壳与动态洞、按人群分段、边缘个性化、部分预渲染。这是缓存的压轴。","frontmatter":{"title":"个性化与缓存 · 每人不同的页面怎么缓存","description":"「你好，张三」这种每人不同的页面，天生和共享缓存(CDN)水火不容——缓存了发给别人就是灾难。可我们又想要 CDN 的速度。这一章给出破局的整套工具：拆分静态壳与动态洞、按人群分段、边缘个性化、部分预渲染。这是缓存的压轴。","source":"https://daiw.org/manual/ssr/personalization"},"headers":[],"relativePath":"manual/computer-programming/ssr/personalization.md","filePath":"manual/computer-programming/ssr/personalization.md"}'),s={name:"manual/computer-programming/ssr/personalization.md"};function o(i,r,l,p,g,c){return e(),n("div",null,[...r[0]||(r[0]=[t(`<h1 id="个性化与缓存-·-每人不同的页面怎么缓存" tabindex="-1">个性化与缓存 · 每人不同的页面怎么缓存 <a class="header-anchor" href="#个性化与缓存-·-每人不同的页面怎么缓存" aria-label="Permalink to &quot;个性化与缓存 · 每人不同的页面怎么缓存&quot;">​</a></h1><p>「你好，张三」这种每人不同的页面，天生和共享缓存(CDN)水火不容——缓存了发给别人就是灾难。可我们又想要 CDN 的速度。这一章给出破局的整套工具：拆分静态壳与动态洞、按人群分段、边缘个性化、部分预渲染。这是缓存的压轴。</p><p>缓存这一站，压轴的是最硬的一块骨头：<strong>个性化内容</strong>。</p><p>矛盾很尖锐。<a href="/Front2Full/manual/computer-programming/ssr/http-caching">HTTP 缓存那章</a> 划过一条红线：<strong>个性化内容必须 <code>private</code>，绝不能进共享缓存</strong>——否则 CDN 把「你好，张三」缓存下来发给李四，就是信息泄露。可另一边，我们又眼馋 <a href="/Front2Full/manual/computer-programming/ssr/cdn-caching">CDN 的速度和扛量</a>。<strong>「每人不同」和「大家共享一份缓存」，天生对立。</strong> 这一章讲怎么破。</p><h2 id="破局的总纲-把「共享的」和「私有的」分开" tabindex="-1">破局的总纲：把「共享的」和「私有的」分开 <a class="header-anchor" href="#破局的总纲-把「共享的」和「私有的」分开" aria-label="Permalink to &quot;破局的总纲：把「共享的」和「私有的」分开&quot;">​</a></h2><p>所有解法都源自同一个洞见：</p><blockquote><p><strong>一个「个性化页面」，极少是 100% 个性化的。</strong> 它通常是<strong>一大片对所有人相同的内容</strong>（布局、文章正文、商品信息、推荐榜）+ <strong>一小撮每人不同的东西</strong>（名字、头像、购物车数量、是否已登录）。</p></blockquote><p>既然如此，就别把整页当成一个不可分的整体去纠结「能不能缓存」。<strong>把共享的部分和私有的部分拆开，各用各的策略：共享的大片，尽情用 CDN 缓存；私有的一小撮，单独实时取。</strong> 下面几种方案，都是这个总纲的不同实现。</p><div class="language-mermaid vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TB</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  subgraph Page[&quot;一个「个性化」页面&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    S[&quot;共享外壳:布局 · 正文 · 榜单&lt;br/&gt;→ CDN 缓存(public),所有人共享,秒回&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    H[&quot;个性化小洞:你好张三 · 购物车(3)&lt;br/&gt;→ 每请求 / 客户端单独取(private)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="方案一-静态壳-客户端补洞" tabindex="-1">方案一：静态壳 + 客户端补洞 <a class="header-anchor" href="#方案一-静态壳-客户端补洞" aria-label="Permalink to &quot;方案一：静态壳 + 客户端补洞&quot;">​</a></h2><p>最经典、最好落地：<strong>把共享外壳做成可缓存的静态页（CDN 秒回），个性化的小洞留空，等页面到了浏览器再用一个客户端请求填上。</strong></p><ul><li>CDN 缓存并秒回那片共享外壳——首屏飞快、SEO 完整（正文都在）。</li><li>页面加载后，一个轻量的客户端请求(<code>/api/me</code>)拉回「张三、购物车 3 件」，填进预留的洞里。</li></ul><p>代价：个性化的小洞有个「先空着、后填上」的短暂闪现。但<strong>用极小的代价，换回了整页的 CDN 缓存</strong>——绝大多数内容站的登录态导航栏就是这么做的。</p><h2 id="方案二-按「人群」分段-而不是按人" tabindex="-1">方案二：按「人群」分段，而不是按人 <a class="header-anchor" href="#方案二-按「人群」分段-而不是按人" aria-label="Permalink to &quot;方案二：按「人群」分段，而不是按人&quot;">​</a></h2><p>有时你不想要客户端补洞的闪现，想让服务端<strong>直接</strong>发出带个性化的完整 HTML，又还能缓存。诀窍：<strong>别按「每个用户」缓存（那是无穷多份，等于没缓存），按「人群段(segment)」缓存。</strong></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>关键是缓存键的「基数(cardinality)」。</strong> 按 <code>user_id</code> 做缓存键 → 一百万用户一百万份缓存，命中率趋零。但如果你的个性化其实只分<strong>几类人群</strong>——「登录 vs 未登录」「中国 vs 海外」「A/B 实验的 A 组 vs B 组」——那就按这个<strong>低基数</strong>的维度缓存：整个站可能只有「登录版」和「未登录版」两份缓存，依然高命中。用 <a href="/Front2Full/manual/computer-programming/ssr/http-caching"><code>Vary</code></a> 或 CDN 的缓存键配置，按这个粗粒度维度分段即可。<strong>个性化 ≠ 一定要精确到人；能降到「按段」，就还能缓存。</strong></p></div><p>典型：未登录访客全看同一份缓存页（占流量大头，缓存价值最高）；登录用户再走个性化路径。仅此一分，就把大部分流量挡在了缓存层。</p><h2 id="方案三-边缘个性化" tabindex="-1">方案三：边缘个性化 <a class="header-anchor" href="#方案三-边缘个性化" aria-label="Permalink to &quot;方案三：边缘个性化&quot;">​</a></h2><p><a href="/Front2Full/manual/computer-programming/ssr/edge-rendering">边缘渲染那章</a> 埋过一个伏笔，这里收：<strong>在边缘节点上，缓存共享外壳，再就地把个性化的小块注入进去。</strong></p><p>边缘节点离用户近、又能读到请求里的 <strong>Cookie</strong>，于是它可以：从边缘缓存取出共享外壳（~0 延迟）→ 从 Cookie 认出用户 / 人群 → 把「你好，张三」就地拼进去 → 发出。<strong>共享部分吃缓存，个性化部分在离用户最近处轻量拼装</strong>，兼得速度与个性化。这类「边缘拼装」的老祖宗是 ESI(Edge Side Includes)，如今被各家边缘中间件现代化地重新实现。</p><h2 id="方案四-部分预渲染-ppr" tabindex="-1">方案四：部分预渲染(PPR) <a class="header-anchor" href="#方案四-部分预渲染-ppr" aria-label="Permalink to &quot;方案四：部分预渲染(PPR)&quot;">​</a></h2><p>框架层最新的答案，是把「静态壳 + 动态洞」做成<strong>一次请求内</strong>的原生能力——<strong>部分预渲染(Partial Prerendering,PPR)</strong>:</p><ul><li><strong>构建时</strong>就把共享外壳<strong>预渲染成静态</strong>（像 SSG，CDN 可缓存）。</li><li>页面里用 <code>&lt;Suspense&gt;</code> 圈出的个性化小洞，则在<strong>每次请求时<a href="/Front2Full/manual/computer-programming/ssr/streaming">流式</a>地</strong>填进那个静态壳里——<strong>在同一个 HTTP 响应内</strong>完成。</li></ul><p>于是用户一个请求就拿到：<strong>静态壳瞬间到达（缓存级速度），个性化的洞随后流式补上（实时）</strong>，没有方案一那种「到浏览器再发第二个请求」的往返。这是「共享缓存」和「实时个性化」一次漂亮的融合——Next.js 16 已将其整合进 Cache Components（<code>cacheComponents: true</code> 配合 <code>&#39;use cache&#39;</code> 与 <code>&lt;Suspense&gt;</code>），Astro 5+ 也提供了思路相通的 <strong>Server Islands（<code>server:defer</code>）</strong>。</p><h2 id="一条必须焊死的纪律" tabindex="-1">一条必须焊死的纪律 <a class="header-anchor" href="#一条必须焊死的纪律" aria-label="Permalink to &quot;一条必须焊死的纪律&quot;">​</a></h2><p>不管用哪个方案，有一条铁律<strong>违反即出事</strong>：</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>绝不让任何一个用户的私有数据，污染共享缓存。</strong> 具体到操作：① 会进共享缓存(<code>public</code>)的响应，<strong>绝不能带 <code>Set-Cookie</code></strong>，也<strong>绝不能</strong>在 HTML 里嵌入任何用户私有数据；② 个性化响应一律 <code>private</code> 或 <code>no-store</code>；③ 拆分时想清楚每一块的「共享 / 私有」归属，别让个性化数据混进「共享外壳」里被缓存走。<strong><a href="/Front2Full/manual/computer-programming/ssr/http-caching">http 缓存那章</a> 说的「张三的页面被发给李四」，几乎都源于这条纪律的破防。</strong> 个性化缓存的所有精巧，都建立在「共享的归共享、私有的归私有」这条界线绝不含糊之上。</p></div><h2 id="小结与下一章" tabindex="-1">小结与下一章 <a class="header-anchor" href="#小结与下一章" aria-label="Permalink to &quot;小结与下一章&quot;">​</a></h2><p>个性化和共享缓存的对立，靠一个总纲破解：<strong>拆开「共享的大片」和「私有的一小撮」，各用各的策略。</strong> 落地有四招——客户端补洞（最好上手）、按人群分段（降基数换命中）、边缘个性化（就近拼装）、部分预渲染（一次请求融合）。而贯穿始终的铁律是：<strong>私有数据绝不能污染共享缓存。</strong></p><p>缓存这一整站（八章）到此讲完——从 HTTP 头到 CDN、SWR、ISR、数据缓存、失效、个性化。你已经有了让 SSR「扛得住」的整套武器。最后一站转向实战：这些东西上了生产，<strong>该量什么指标、怎么排查</strong>。👉 <a href="/Front2Full/manual/computer-programming/ssr/measuring">量化与排查：TTFB、LCP 与缓存命中率</a>。</p><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><ul><li>[1] Next.js 文档.「Partial Prerendering.」<a href="https://nextjs.org/docs/app/building-your-application/rendering/partial-prerendering" target="_blank" rel="noreferrer">https://nextjs.org/docs/app/building-your-application/rendering/partial-prerendering</a> —— PPR 的静态壳 + 动态洞模型。</li><li>[2] Fastly / Akamai.「Edge Side Includes (ESI) / edge personalization.」<a href="https://www.fastly.com/documentation/" target="_blank" rel="noreferrer">https://www.fastly.com/documentation/</a> —— 边缘拼装个性化。</li><li>[3] web.dev.「Cache API + personalization patterns.」<a href="https://web.dev/articles/rendering-on-the-web" target="_blank" rel="noreferrer">https://web.dev/articles/rendering-on-the-web</a> —— 静态壳 + 客户端补洞、按段缓存。</li></ul>`,32)])])}const u=a(s,[["render",o]]);export{h as __pageData,u as default};
